insert into public.demo_suppliers (seed_key, name, category, country, spend, delivery, quality, price_competitiveness, dependency_risk, contract_expiry, incidents, flags, notes)
 select seed_key, name, category, country, spend, delivery, quality, price_competitiveness, dependency_risk, contract_expiry, incidents, flags, notes from jsonb_populate_recordset(null::public.demo_suppliers, '[{"seed_key":"S001","name":"Hartwell Components","category":"Electronics","country":"UK","spend":320000,"delivery":97,"quality":9.2,"price_competitiveness":"High","dependency_risk":"High","contract_expiry":8,"incidents":0,"flags":["High dependency","Contract expiring soon"],"notes":"Primary supplier for core electronics. Excellent delivery and quality. However single-source dependency and contract expiry in 8 months creates significant risk. Renewal negotiations should begin immediately."},{"seed_key":"S002","name":"Meridian Packaging","category":"Packaging","country":"Germany","spend":185000,"delivery":94,"quality":8.7,"price_competitiveness":"High","dependency_risk":"Medium","contract_expiry":18,"incidents":1,"flags":[],"notes":"Strong performer with one minor quality incident resolved quickly. Good price competitiveness. Contract has 18 months remaining. Low overall risk."},{"seed_key":"S003","name":"Apex Textiles","category":"Clothing","country":"Bangladesh","spend":240000,"delivery":78,"quality":7.1,"price_competitiveness":"Medium","dependency_risk":"Medium","contract_expiry":4,"incidents":4,"flags":["Poor delivery","Multiple incidents","Contract expiring"],"notes":"Delivery performance has dropped significantly over the past year. Four quality incidents recorded. Contract expires in 4 months. Needs urgent performance review before renewal decision."},{"seed_key":"S004","name":"Sterling Logistics","category":"Logistics","country":"UK","spend":410000,"delivery":91,"quality":8.4,"price_competitiveness":"Medium","dependency_risk":"High","contract_expiry":12,"incidents":2,"flags":["High dependency","Above average incidents"],"notes":"Highest spend supplier. Single-source logistics provider. Two incidents in past year. High dependency risk. Contract has 12 months remaining. Alternative provider identification recommended."},{"seed_key":"S005","name":"Nova Print Solutions","category":"Print and Marketing","country":"UK","spend":95000,"delivery":99,"quality":9.5,"price_competitiveness":"High","dependency_risk":"Low","contract_expiry":24,"incidents":0,"flags":[],"notes":"Exceptional delivery and quality scores. Low dependency risk. Competitive pricing. Contract has 24 months remaining. Strong and stable supplier relationship."},{"seed_key":"S006","name":"Eastern Raw Materials","category":"Raw Materials","country":"China","spend":175000,"delivery":82,"quality":6.8,"price_competitiveness":"Low","dependency_risk":"Medium","contract_expiry":3,"incidents":5,"flags":["Poor delivery","Low quality rating","Multiple incidents","Contract expiring","Geopolitical risk"],"notes":"Below acceptable delivery threshold. Quality rating is below minimum standard of 7.0. Five incidents in 12 months. Contract expires in 3 months. Geopolitical supply chain risk. Urgent replacement sourcing required."},{"seed_key":"S007","name":"Pinnacle Tech Parts","category":"Electronics","country":"Taiwan","spend":155000,"delivery":88,"quality":7.9,"price_competitiveness":"Medium","dependency_risk":"Medium","contract_expiry":14,"incidents":1,"flags":["Geopolitical risk"],"notes":"Good overall performance with one incident. Medium dependency. However geopolitical risk from Taiwan supply chain should be monitored. Contract has 14 months remaining."}]'::jsonb)
 on conflict do nothing;

insert into public.demo_leads (seed_key, company, industry, contact, lead_source, budget_gbp, timeline_months, decision_makers, previous_engagement, pain_point_clarity, fit_score, flags_str, notes)
 select seed_key, company, industry, contact, lead_source, budget_gbp, timeline_months, decision_makers, previous_engagement, pain_point_clarity, fit_score, flags_str, notes from jsonb_populate_recordset(null::public.demo_leads, '[{"seed_key":"L001","company":"Meridian Logistics","industry":"Logistics","contact":"Sarah Chen","lead_source":"Inbound","budget_gbp":45000,"timeline_months":2,"decision_makers":3,"previous_engagement":"Demo attended | Follow-up replied","pain_point_clarity":"High","fit_score":92,"flags_str":"None","notes":"Strong budget and timeline. Clear pain point around route optimisation. Multiple decision makers engaged."},{"seed_key":"L002","company":"Apex Retail Group","industry":"Retail","contact":"James Okafor","lead_source":"Referral","budget_gbp":38000,"timeline_months":3,"decision_makers":2,"previous_engagement":"Intro call done | Proposal requested","pain_point_clarity":"High","fit_score":88,"flags_str":"None","notes":"Referred by existing client. Requested proposal within 48 hours of first call. Budget confirmed."},{"seed_key":"L003","company":"Northgate Healthcare","industry":"Healthcare","contact":"Dr Priya Patel","lead_source":"Outbound","budget_gbp":62000,"timeline_months":6,"decision_makers":5,"previous_engagement":"Intro call done","pain_point_clarity":"Medium","fit_score":74,"flags_str":"Long sales cycle | Many stakeholders","notes":"Large deal but procurement process is complex. Requires board approval. Timeline is 6 months minimum."},{"seed_key":"L004","company":"Falcon Manufacturing","industry":"Manufacturing","contact":"Tom Briggs","lead_source":"Inbound","budget_gbp":28000,"timeline_months":4,"decision_makers":2,"previous_engagement":"Demo attended","pain_point_clarity":"Medium","fit_score":71,"flags_str":"Budget below average | Single champion","notes":"Only one internal champion identified. Budget is below average for this solution tier. Risk of stalling."},{"seed_key":"L005","company":"Sterling Financial","industry":"Finance","contact":"Amanda Walsh","lead_source":"Event","budget_gbp":55000,"timeline_months":3,"decision_makers":4,"previous_engagement":"No engagement since event","pain_point_clarity":"Low","fit_score":58,"flags_str":"No follow-up | Low engagement","notes":"Met at industry event. No response to two follow-up emails. Pain point not clearly articulated."},{"seed_key":"L006","company":"Horizon EdTech","industry":"Education","contact":"Marcus Lee","lead_source":"Outbound","budget_gbp":18000,"timeline_months":8,"decision_makers":1,"previous_engagement":"Intro call done","pain_point_clarity":"Low","fit_score":42,"flags_str":"Low budget | Long timeline | Single decision maker","notes":"Budget is significantly below minimum viable deal size. Timeline is 8 months. Only one decision maker."},{"seed_key":"L007","company":"Crestwood Legal","industry":"Legal","contact":"Fiona Grant","lead_source":"Inbound","budget_gbp":41000,"timeline_months":3,"decision_makers":3,"previous_engagement":"Demo attended | Trial requested","pain_point_clarity":"High","fit_score":86,"flags_str":"None","notes":"Requested a trial after demo. Three decision makers actively involved. Clear pain point around document management."},{"seed_key":"L008","company":"Delta Construction","industry":"Construction","contact":"Ryan Murphy","lead_source":"Outbound","budget_gbp":22000,"timeline_months":5,"decision_makers":1,"previous_engagement":"No engagement","pain_point_clarity":"Low","fit_score":35,"flags_str":"No engagement | Low budget | Outside core ICP","notes":"No response to any outreach. Budget and industry are outside core ideal customer profile. Low priority."}]'::jsonb)
 on conflict do nothing;

insert into public.demo_properties (seed_key, address, type, region, asking_price, estimated_market_value, monthly_rent, annual_service_charge, annual_maintenance, vacancy_risk, condition, title_status, flags, notes)
 select seed_key, address, type, region, asking_price, estimated_market_value, monthly_rent, annual_service_charge, annual_maintenance, vacancy_risk, condition, title_status, flags, notes from jsonb_populate_recordset(null::public.demo_properties, '[{"seed_key":"P001","address":"14 Specimen Road, Manchester","type":"Residential Terraced","region":"North West","asking_price":185000,"estimated_market_value":195000,"monthly_rent":1050,"annual_service_charge":0,"annual_maintenance":1800,"vacancy_risk":"Low","condition":"Good","title_status":"Freehold","flags":[],"notes":"Below market value. Strong rental demand in area. No service charge. Freehold title. Long-term tenant in situ."},{"seed_key":"P002","address":"Apt 7 Sample Court, Leeds","type":"Residential Apartment","region":"Yorkshire","asking_price":162000,"estimated_market_value":158000,"monthly_rent":900,"annual_service_charge":2400,"annual_maintenance":1200,"vacancy_risk":"Low","condition":"Very Good","title_status":"Leasehold","flags":["Above asking vs market"],"notes":"Above market value asking price. High service charge reduces net yield. Popular area with strong tenant demand."},{"seed_key":"P003","address":"Unit 4 Example Business Centre, Birmingham","type":"Commercial Unit","region":"West Midlands","asking_price":275000,"estimated_market_value":290000,"monthly_rent":2100,"annual_service_charge":3600,"annual_maintenance":2400,"vacancy_risk":"Medium","condition":"Good","title_status":"Freehold","flags":[],"notes":"Below market value. Strong commercial tenant on 3-year lease. Higher maintenance but solid yield. Freehold title."},{"seed_key":"P004","address":"22 Demo Avenue, Bristol","type":"Residential Terraced","region":"South West","asking_price":220000,"estimated_market_value":215000,"monthly_rent":1100,"annual_service_charge":0,"annual_maintenance":2200,"vacancy_risk":"Low","condition":"Average","title_status":"Freehold","flags":["Above asking vs market","Requires refurbishment"],"notes":"Slightly above market value. Requires kitchen and bathroom refurbishment estimated at GBP 18,000. Freehold but margin is tight after works."},{"seed_key":"P005","address":"Flat 12 The Illustration, London","type":"Residential Apartment","region":"London","asking_price":485000,"estimated_market_value":470000,"monthly_rent":2200,"annual_service_charge":6000,"annual_maintenance":1800,"vacancy_risk":"Medium","condition":"Good","title_status":"Leasehold","flags":["Above asking vs market","High service charge","Short lease"],"notes":"Above market value. Service charge is very high. Lease has only 74 years remaining — requires extension which could cost GBP 25,000 to GBP 40,000. Significant risk."},{"seed_key":"P006","address":"8 Placeholder Road, Newcastle","type":"Residential Terraced","region":"North East","asking_price":128000,"estimated_market_value":138000,"monthly_rent":780,"annual_service_charge":0,"annual_maintenance":1400,"vacancy_risk":"Low","condition":"Good","title_status":"Freehold","flags":[],"notes":"Significantly below market value. Strong rental yield. Freehold. Low maintenance costs. High demand area near university."}]'::jsonb)
 on conflict do nothing;
